import{_ as t,c as o,o as a,ag as s}from"./chunks/framework.DZ_cNctr.js";const i="/docs/screenshots/czi-image.webp",g=JSON.parse('{"title":"Zeiss CZI Files in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Zeiss CZI files from ZEN in your browser: Z-stacks, scenes, mosaics and Celldiscoverer 7 plates. Free, nothing to install.","frontmatter":{"title":"Zeiss CZI Files in the Browser","titleTemplate":"Find Nuclei: :title","description":"Find Nuclei opens Zeiss CZI files from ZEN in your browser: Z-stacks, scenes, mosaics and Celldiscoverer 7 plates. Free, nothing to install."},"headers":[],"relativePath":"guides/zeiss-czi.md","filePath":"guides/zeiss-czi.md"}'),r={name:"guides/zeiss-czi.md"};function n(l,e,d,h,p,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="zeiss-czi-files-in-the-browser" tabindex="-1">Zeiss CZI Files in the Browser <a class="header-anchor" href="#zeiss-czi-files-in-the-browser" aria-label="Permalink to &quot;Zeiss CZI Files in the Browser&quot;">​</a></h1><p>Open the files ZEN saves, as they are. Nothing to convert, nothing to upload. A large file starts showing right away, because the viewer reads only the part you look at.</p><img width="1500" height="950" src="'+i+'" alt="BODIPY2_DFO_rep1.czi open in the viewer: a confocal image in three channels, nuclei in blue and lipid droplets in yellow and orange, with each channel&#39;s contrast in the panel" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"><h2 id="how-it-opens" tabindex="-1">How It Opens <a class="header-anchor" href="#how-it-opens" aria-label="Permalink to &quot;How It Opens&quot;">​</a></h2><ul><li><strong>One file on your disk</strong>, in any browser. Drop it on the viewer, or click <strong>Open Image</strong> and <strong>Choose File</strong>. See <a href="./local-files.html#open-a-file">Local Files</a>.</li><li><strong>A plate saved as one file per field</strong>, as a folder in Chrome and Edge, or as a zip in any browser. See <a href="#plates-saved-as-one-file-per-field">Plates Saved as One File per Field</a>.</li><li><strong>An address</strong>: <code>https://</code>, <code>s3://</code> or <code>gs://</code>. Paste it under <strong>Open Image</strong>. See <a href="./remote-urls.html">Remote URLs</a>.</li><li><strong>Private data</strong>, with a private link or a token. See <a href="./authenticated-sources.html">Private Images and Slides</a>.</li></ul><p>A Z-stack can also be viewed in 3D, whichever of these it was opened from. See <a href="./3d-rendering.html#requirements-and-limits">3D Rendering</a>.</p><h2 id="what-you-will-see" tabindex="-1">What You Will See <a class="header-anchor" href="#what-you-will-see" aria-label="Permalink to &quot;What You Will See&quot;">​</a></h2><ul><li><strong>Z-stacks, time series and channels.</strong> Move through Z and time. Z-stacks open in 3D too.</li><li><strong>Scenes.</strong> A file with several scenes opens as a series. Pick a scene from the <strong>Series</strong> list.</li><li><strong>Illumination, view, phase, rotation and block.</strong> Each opens as a list to choose from. Each entry shows only its own images.</li><li><strong>Mosaics.</strong> Tiles are stitched at the positions ZEN recorded.</li><li><strong>Lower resolutions.</strong> When ZEN saved them, zooming out stays fast.</li><li><strong>Well plates, Celldiscoverer 7 included.</strong> A plate opens with the well navigator and the well picker. See <a href="#plates">Plates</a>.</li><li><strong>Colours.</strong> Channels open in the colours you set in ZEN.</li><li><strong>Pixel types.</strong> 8-bit and 16-bit grayscale, and 8-bit and 16-bit RGB.</li><li><strong>Compression.</strong> Uncompressed, Zstd and JPEG XR files open.</li><li><strong>Pixel size and magnification.</strong> The pixel size comes from the file, and the magnification from the objective the image names. To set your own, see <a href="./calibration.html">Pixel Size and Magnification</a>.</li></ul><p>A file without a pixel size opens at scale 1. The Image Information dialog says so, and you can enter one there.</p><h2 id="plates" tabindex="-1">Plates <a class="header-anchor" href="#plates" aria-label="Permalink to &quot;Plates&quot;">​</a></h2><p>A plate in a CZI holds each field at one resolution, with no pyramid. Plate and Well view open when their images fit in 256 MB: Plate view holds one field per well, Well view every field of one well. A 96-well plate with four 640 x 640 fields per well needs 3 MB. A larger plate opens in Field view, and a note under the Field | Well | Plate toggle says so. The <a href="./opera-phenix-plates.html#why-there-is-no-plate-or-well-view">Opera Phenix guide</a> explains why.</p><p>Want Plate view for a large plate? Convert the file to OME-Zarr.</p><p>A file with scenes but no plate layout opens as a series of scenes. Plates are read the way <a href="https://github.com/sebi06/czitools" target="_blank" rel="noreferrer">czitools</a> reads them.</p><p>Try one: the <strong>Zeiss CZI</strong> tile in the Example Gallery opens a real plate.</p><h2 id="plates-saved-as-one-file-per-field" tabindex="-1">Plates Saved as One File per Field <a class="header-anchor" href="#plates-saved-as-one-file-per-field" aria-label="Permalink to &quot;Plates Saved as One File per Field&quot;">​</a></h2><p>Some instruments save every field of a plate as its own CZI file. <a href="https://idr.openmicroscopy.org" target="_blank" rel="noreferrer">IDR</a> idr0011 is one example. The viewer puts them back together as one plate.</p><p><strong>A folder.</strong> Drop the folder on the viewer. Or click <strong>Open Image</strong>, go to the <strong>Local Files</strong> tab and click <strong>Choose Data Folder</strong>. Folders open in Chrome and Edge. In Firefox and Safari, use a zip.</p><p><strong>A zip.</strong> Zip the folder without compression. Then drop the <code>.zip</code> on the viewer, or click <strong>Choose File</strong> on the <strong>Local Files</strong> tab, or paste its web address. On a Mac, in Terminal:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>zip -0 -r plate.zip folder</span></span></code></pre></div><p>On Windows, see <a href="./local-files.html#zip-without-compression">Zip Without Compression</a>. A compressed zip is refused, and the message says so.</p><p><strong>How wells are found.</strong> Wells come from the file&#39;s own records, never from the file name. Fields in a well follow the time they were taken.</p><p><strong>A folder that holds several things.</strong> A list titled <strong>Choose a dataset</strong> appears. Pick a row to open it.</p><ul><li><strong>A plate.</strong> The row shows how many fields and wells it holds.</li><li><strong>An image.</strong> A single file. When a file does not fit its plate, the row says why. For example, its channels or pixel size differ from the rest.</li><li><strong>A file that cannot be read.</strong> The row is greyed out and gives the reason, such as &quot;Not a CZI file.&quot;</li></ul><p>A folder that holds one thing opens straight away.</p><p><strong>One field alone.</strong> Open one field file and you see one field. The viewer tells you: &quot;This file is one field of a plate. Drop the whole folder to see the plate.&quot;</p><h2 id="if-a-file-does-not-open" tabindex="-1">If a File Does Not Open <a class="header-anchor" href="#if-a-file-does-not-open" aria-label="Permalink to &quot;If a File Does Not Open&quot;">​</a></h2><p>The viewer tells you why, and what to do.</p><table tabindex="0"><thead><tr><th>What the file has</th><th>What the viewer says</th></tr></thead><tbody><tr><td>JPG, LZW or another compression</td><td>This CZI file uses a compression the viewer cannot read yet (JPG). In ZEN, save a copy without compression or with Zstd, and open that.</td></tr><tr><td>32-bit float pixels</td><td>This CZI file stores Gray32Float pixels. The viewer reads 8-bit, 16-bit and RGB images.</td></tr><tr><td>Channels of different pixel types</td><td>This CZI file mixes pixel types across channels (Gray8, Gray16). The viewer cannot show them together yet.</td></tr><tr><td>A large mosaic with no lower resolutions</td><td>This scene is a large tiled image with no lower resolutions stored, so the viewer cannot show it yet. In ZEN, save a copy with a pyramid, and open that.</td></tr><tr><td>A plate with another dimension: rotation, illumination, phase, view or block</td><td>This CZI plate has more than one phase (2). The viewer cannot show that dimension on a plate yet.</td></tr><tr><td>A file still open in ZEN</td><td>This CZI file was not closed by ZEN, so it may be incomplete. Open it in ZEN and save it again.</td></tr><tr><td>A file split into parts</td><td>This CZI file is split into parts. The viewer opens single-file CZI only.</td></tr><tr><td>A compressed zip</td><td>{zip}: The CZI files in this zip are compressed, so they cannot be read in parts. Make the zip without compression (for example zip -0 -r plate.zip folder) and open that.</td></tr><tr><td>A very large file with no index</td><td>This CZI file is too large to open without an index. An index for large files is planned.</td></tr><tr><td>Not a CZI</td><td>This file is not a CZI file.</td></tr></tbody></table><p><strong>One fix for most of them.</strong> In ZEN, save a copy without compression or with Zstd, and open the copy. For a big mosaic, save it with a pyramid.</p><p><strong>Big mosaics.</strong> A tiled scene wider or taller than 3000 pixels needs lower resolutions saved with it. A scene of one tile always opens.</p><p><strong>Converting instead.</strong> <a href="https://www.openmicroscopy.org/bio-formats/" target="_blank" rel="noreferrer">Bio-Formats</a> turns a CZI into OME-Zarr. The <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">conversion guide</a> shows how.</p><h2 id="public-czi-files-to-try" tabindex="-1">Public CZI Files to Try <a class="header-anchor" href="#public-czi-files-to-try" aria-label="Permalink to &quot;Public CZI Files to Try&quot;">​</a></h2><ul><li><strong>Zenodo.</strong> Opens by address. Use the link that ends in <code>/content</code>, such as <code>https://zenodo.org/api/records/7015307/files/W96_B2+B4_S=2_T=1=Z=1_C=1_Tile=5x9.czi/content</code>. A link that ends in <code>?download=1</code> does not open. Try <a href="https://zenodo.org/records/10577186" target="_blank" rel="noreferrer">record 10577186</a> and <a href="https://zenodo.org/records/11234863" target="_blank" rel="noreferrer">record 11234863</a>. Both are CC BY 4.0.</li><li><strong>OpenSlide test data.</strong> The <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/Zeiss/" target="_blank" rel="noreferrer">Zeiss folder</a>, CC0. Download a file, then drop it on the viewer.</li><li><strong>Bio-Formats sample images.</strong> The <a href="https://downloads.openmicroscopy.org/images/Zeiss-CZI/" target="_blank" rel="noreferrer">Zeiss-CZI folder</a>. Download a file first, the same way.</li></ul><p>More places to find public data: <a href="./remote-urls.html">Remote URLs</a>.</p><h2 id="for-your-it-team" tabindex="-1">For Your IT Team <a class="header-anchor" href="#for-your-it-team" aria-label="Permalink to &quot;For Your IT Team&quot;">​</a></h2><p>To open a CZI by address, the server must answer byte-range requests and allow them through <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS" target="_blank" rel="noreferrer">CORS</a>. For a bucket, allow <code>GET</code> and the <code>Range</code> header in its CORS rules. <a href="./remote-urls.html#what-the-server-needs">What the Server Needs</a> has the details.</p><p>When a server cannot send parts of a file, the viewer says so. Download the file and open it from your computer. A server that limits requests may slow a large mosaic, since each tile is one request.</p><h2 id="third-party-notices" tabindex="-1">Third-party notices <a class="header-anchor" href="#third-party-notices" aria-label="Permalink to &quot;Third-party notices&quot;">​</a></h2><p>The JPEG XR decoder&#39;s licence: <a href="/docs/third-party-notices.txt">Third-party notices</a>.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>The file is read in your browser. Opening a CZI counts as one opened image of the kind &quot;Zeiss CZI file&quot;. The file name and address are never recorded. See the <a href="https://find-nuclei.github.io/privacy.html" target="_blank" rel="noreferrer">privacy policy</a>.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshot uses <code>BODIPY2_DFO_rep1.czi</code> from BioImage Archive study S-BIAD4045, CC0. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><p><small>Product names are trademarks of their owners. Find Nuclei is not affiliated with them.</small></p>',44)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
